changeSet.sql:
UPDATE krrg_vacancies
SET status = 'NEW'
WHERE status IS NULL OR status <> 'NEW';

ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS request_status VARCHAR(50);
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS actual_on DATE;
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS extendable BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS workload_level VARCHAR(50);
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS workload_hours_per_month INTEGER;
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS availability_utc_offset INTEGER;
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS client_payment_terms TEXT;
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS client_reviews_count INTEGER;
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS requirements TEXT;
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS additional_requirements TEXT;
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS selection_stages TEXT;
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS joining_conditions TEXT;
ALTER TABLE krrg_vacancies ADD COLUMN IF NOT EXISTS details_loaded BOOLEAN NOT NULL DEFAULT FALSE;

