ALTER TABLE krrg_vacancies DROP COLUMN IF EXISTS client_reviews_count;
ALTER TABLE krrg_vacancies DROP COLUMN IF EXISTS requirements;
ALTER TABLE krrg_vacancies DROP COLUMN IF EXISTS additional_requirements;
ALTER TABLE krrg_vacancies DROP COLUMN IF EXISTS selection_stages;
ALTER TABLE krrg_vacancies DROP COLUMN IF EXISTS joining_conditions;
