changeSet.sql:
ALTER TABLE krrg_vacancies DROP CONSTRAINT IF EXISTS krrg_vacancies_status_check;
ALTER TABLE krrg_vacancies ADD CONSTRAINT krrg_vacancies_status_check
    CHECK (status IN ('NEW', 'IN_ENRICHMENT', 'ENRICHED', 'FAILED', 'SKIPPED'));

rollback.sql:
ALTER TABLE krrg_vacancies DROP CONSTRAINT IF EXISTS krrg_vacancies_status_check;
ALTER TABLE krrg_vacancies ADD CONSTRAINT krrg_vacancies_status_check
    CHECK (status IN ('NEW', 'ENRICHED', 'FAILED'));

changeSet.sql:
ALTER TABLE krrg_vacancies DROP CONSTRAINT IF EXISTS krrg_vacancies_status_check;
ALTER TABLE krrg_vacancies ADD CONSTRAINT krrg_vacancies_status_check
    CHECK (status IN ('NEW', 'IN_ENRICHMENT', 'ENRICHED', 'FAILED', 'SKIPPED', 'READY'));

